/**
 * Shape of papers.json. Shared by <Cite> and the papers widget.
 * papers.json is generated by scripts/build_papers.py from ../literature/ (facts) and
 * src/data/papers/curation.toml (themes, "why it matters", relations). Edit those, not the JSON.
 */
export interface Theme {
  id: string;
  label: string;
  description?: string;
  /** Short label for a lane of the timeline (falls back to label). */
  short?: string;
  /** Colour token from tokens.css, e.g. "--h". */
  color?: string;
}
export type RelationKind =
  | 'reduces-from'   // A's hardness proof reduces from the problem of B
  | 'builds-on'      // A uses a result, gadget or technique of B
  | 'extends'        // A strengthens or generalises B
  | 'variant-of'     // A studies a variant of the problem in B
  | 'refutes'        // A finds an error in B
  | 'surveys'        // A surveys / restates B
  | 'formalizes'     // A formalizes something from B
  | 'answers'        // A answers a question left open in B
  | 'discusses';     // A discusses or critiques B without changing its result
export interface Relation {
  to: string;
  kind: RelationKind;
  note?: string;
}
/** How far the team read the source (literature/INDEX.md vocabulary). */
export type ReadStatus = 'read' | 'skim' | 'abstract' | 'todo';
export interface Paper {
  key: string;
  year: number;
  authors: string[]; // surnames
  title: string;
  venue?: string;
  url?: string;
  themes: string[]; // the first one is the paper's lane
  relevance: 1 | 2 | 3;
  /** One clause on what the paper shows: the line a reader sees by default. */
  gist: string;
  /** More on what the paper does, shown on demand after the gist (it does not repeat it). */
  takeaway?: string;
  badge?: string; // short qualifier shown next to the name, e.g. "3D cubic lattice"
  why?: string; // why it matters for this problem, 1–2 sentences
  relations?: Relation[];
  status?: ReadStatus;
  statusNote?: string; // e.g. how the team knows a source it has not read
}
export interface PapersData {
  themes: Theme[];
  papers: Paper[];
}

export function shortAuthors(p: Paper): string {
  const a = p.authors;
  if (a.length === 1) return a[0];
  if (a.length === 2) return `${a[0]} & ${a[1]}`;
  return `${a[0]} et al.`;
}
